import stripe

@app.post('/stripe/webhook')
async def stripe_webhook(request: Request):
    payload = await request.body()
    sig_header = request.headers.get('stripe-signature')
    try:
        event = stripe.Webhook.construct_event(payload, sig_header, STRIPE_WEBHOOK_SECRET)
    except Exception:
        raise HTTPException(status_code=400)
    if event.type in ['payment_intent.succeeded', 'customer.subscription.created', 'invoice.payment_succeeded']:
        await event_bus.emit(f"garcar.{SYSTEM_ID}.revenue.signal", {"amount": event.data.object.get('amount_received', 0), "attribution": ATTRIBUTION_CODE, "stripe_event": event.type})
    return {"status": "processed"}

