import redis.asyncio as redis
import json

class GarcarEventBus:
    def __init__(self):
        self.redis = redis.from_url(REDIS_URL)
    async def emit(self, event_type: str, payload: dict):
        await self.redis.xadd("garcar:events", {"type": event_type, "payload": json.dumps(payload), "system": SYSTEM_ID})
    async def consume(self, event_pattern: str, handler):
        while True:
            msgs = await self.redis.xread({"garcar:events": "$"}, block=1000)
            for _, entries in msgs:
                for _, fields in entries:
                    if fields[b'type'].decode().startswith(event_pattern):
                        await handler(json.loads(fields[b'payload']))

event_bus = GarcarEventBus()

