import asyncio

async def self_healing_loop():
    while True:
        try:
            await asyncio.sleep(30)
            status = await check_all_dependencies()
            for dep, healthy in status.items():
                if not healthy:
                    await restart_dependency(dep)
                    await event_bus.emit(f'garcar.{SYSTEM_ID}.self_healed', {"dependency": dep, "action": "restarted"})
        except Exception as e:
            await event_bus.emit(f'garcar.{SYSTEM_ID}.heal_failed', {"error": str(e)})
